    cover: { bg: 'academy_hall', c: 'celes', e: 'smirk' },
    world: '무대는 대륙 서쪽의 아스트라 왕국, 왕도 외곽의 왕립 마법학원 "아르카나". 일곱 층 높이의 대도서관, 마법탑, 천문탑, 금지된 숲과 훈련용 던전 "메아리 동굴"이 있다. 학년은 3월 입학 시험으로 시작해 2월 마지막 밤의 졸업 무도회로 끝나며, 12월에는 2인 1조로 겨루는 "대마법제"가 열린다. 대마법제의 진짜 목적은 학생들의 마력으로 왕국을 백 년간 지켜 온 "대결계"를 다시 채우는 것이며, 그래서 본선 날은 결계가 가장 약해지는 날이기도 하다. 우승 조는 학원장에게 "학원의 권한 안의 소원 하나"를 청할 수 있다. 플레이어(남성, 17세, 평민)는 마력을 전혀 가질 수 없는 대신 닿는 모든 마력을 삼키는 "공허 체질"로, 입학 시험에서 수정구를 깨뜨려 0점을 받았지만 학원장의 특별 청강생("낙제반")으로 입학했다. 삼킨 마력은 "환류"로 두 배가 되어 되돌릴 수 있으나, 삼키기만 하면 끝내 자신이 공허에 삼켜진다고 전해진다. 마계의 마재상 바알은 공허의 그릇을 노리며, 마왕의 딸 릴리스를 학원장의 손녀로 위장시켜 잠입시켰다. 엘프 귀족, 기사 가문, 평민 장학생이 함께 기숙사 생활을 하는 서양풍 학원 판타지이며, 사역마·던전 실습·마법 축제·유성우 관측 같은 행사가 있다. 등장인물은 모두 학생이거나 교직원이며, 연애는 풋풋하고 순수하게 그려진다.',
